dataTableFormat:
{
    "data convert": [
        {
            "type": "raw",
            "field name": "Sentinel Variant (rsID)",
            "raw field": "Sentinel Variant"
        },
        {
            "type": "raw",
            "field name": "Chromosome",
            "raw field": "Chr"
        },
        {
            "type": "raw",
            "field name": "Position (hg19)",
            "raw field": "hg19"
        },
        {
            "type": "replace characters",
            "field name": "Nearest Gene(s)",
            "raw field": "Nearest Gene(s)",
            "replace": [
                {
                    "from": ",",
                    "to": "; "
                }
            ]
        },
        {
            "type": "raw",
            "field name": "GTEx Heart Expression",
            "raw field": "GTEx Heart Expression"
        },
        {
            "type": "raw",
            "field name": "Genes within enriched pathways",
            "raw field": "Within enriched pathways in GSEA"
        },
        {
            "type": "raw",
            "field name": "Known vs. Novel Locus",
            "raw field": "Known vs. Novel"
        },
        {
            "type": "raw",
            "field name": "eQTL MAGNet Left Atrial",
            "raw field": "eQTL MAGNet Left Atrial"
        },
        {
            "type": "raw",
            "field name": "eQTL GTEx Heart",
            "raw field": "eQTL GTEx Heart*"
        },
        {
            "type": "raw",
            "field name": "MetaXcan Heart",
            "raw field": "MetaXcan Heart*"
        },
        {
            "type": "join",
            "field name": "All Genes",
            "fields to join": [
                "Nearest Gene(s)",
                "GTEx Heart* Expression (median RPKM)",
                "Within enriched pathways in GSEA",
                "eQTL MAGNet Left Atrial",
                "eQTL GTEx Heart*",
                "MetaXcan Heart*"
            ],
            "join by": " "
        },
        {
            "type": "join",
            "field name": "Sentinel",
            "fields to join": ["Chr", "Sentinel Variant"],
            "join by": " "
        },
        {
            "type": "join",
            "field name": "Locus",
            "fields to join": ["Chr", "hg19"],
            "join by": ":"
        }
    ],
    "column formatting": {
        "Sentinel Variant (rsID)": {
            "type": ["link"],
            "link to": "https://cvd.hugeamp.org/variant.html?variant=",
            "new tab": "true"
        }
    },
    "tool tips": {
        "GTEx Heart Expression": "Gene expression (median RPKM) in heart left ventricle and heart atrial appendage, from GTEx",
        "Genes within enriched pathways": "Gene listed if within 500kb of sentinel variant and present in at least one enriched pathway as identified by gene set enrichment analysis",
        "eQTL MAGNet Left Atrial": "Genes linked to eQTLs in left atrial samples without structural heart disease from the Myocardial Applied Genomics Network repository",
        "eQTL GTEx Heart": "Genes linked to eQTLs in left atrial samples without structural heart disease from the Myocardial Applied Genomics Network repository",
        "MetaXcan Heart": "Predicted association between gene expression in left ventricle and right atrial appendage and risk of atrial fibrillation"
    },
    "top rows": [
        "Sentinel Variant (rsID)",
        "Chromosome",
        "Locus",
        "Nearest Gene(s)",
        "GTEx Heart Expression",
        "Genes within enriched pathways",
        "eQTL MAGNet Left Atrial",
        "eQTL GTEx Heart",
        "MetaXcan Heart",       
        "Known vs. Novel Locus"
    ]
}

